        "import type { WritableSignal } from '@angular/core';\n\nimport { ChangeDetectionStrategy, Component, signal } from '@angular/core';\n\nimport { Autocomplete } from '@filip.mazev/blocks/forms';\n@Component({ selector: 'app-example', imports: [Autocomplete], changeDetection: ChangeDetectionStrategy.OnPush, templateUrl: './example.html' })\nexport class Example {\n  public readonly __FIELDS__: WritableSignal<unknown> = signal<unknown>(undefined);\n}\n"
